/// <summary>
/// One order line, in and out: what the worker captured, and what D365FO priced, found in stock or created. Also one stock row of getStock (batch, serial, available).
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderLine
{
    real lineNumber;
    str itemId;
    str itemName;
    str configId;
    str sizeId;
    str colorId;
    str styleId;
    str batchId;
    str serialId;
    real qty;
    str unitId;
    real price;
    real priceUnit;
    boolean priceOverride;
    real discPct;
    real discAmount;
    real lineAmount;
    str priceSource;
    real available;
    str message;
    str locationId;
}

