/// <summary>
/// Lines from a JSON array of this class's members, as the handheld sends them. Missing
/// members read as blank / zero / false.
/// </summary>
public static List listFromJson(str _json)
{
    List                         result = new List(Types::Class);
    System.Object                parsed;
    Newtonsoft.Json.Linq.JArray  jArray;
    Newtonsoft.Json.Linq.JObject jLine;
    HSMobileOpsOrderLine         line;
    int                          lineCount;
    int                          i;

    if (!_json)
    {
        return result;
    }
    try
    {
        parsed = Newtonsoft.Json.Linq.JArray::Parse(_json);
    }
    catch (Exception::CLRError)
    {
        return result;
    }
    jArray = parsed;
    if (jArray == null)
    {
        return result;
    }

    lineCount = jArray.get_Count();
    for (i = 0; i < lineCount; i++)
    {
        jLine = jArray.get_Item(i);
        if (jLine == null)
        {
            continue;
        }
        line = new HSMobileOpsOrderLine();
        line.parmLineNumber(HSMobileOpsOrderLine::jsonNum(jLine, 'LineNumber'));
        line.parmItemId(HSMobileOpsOrderLine::jsonStr(jLine, 'ItemId'));
        line.parmItemName(HSMobileOpsOrderLine::jsonStr(jLine, 'ItemName'));
        line.parmConfigId(HSMobileOpsOrderLine::jsonStr(jLine, 'ConfigId'));
        line.parmSizeId(HSMobileOpsOrderLine::jsonStr(jLine, 'SizeId'));
        line.parmColorId(HSMobileOpsOrderLine::jsonStr(jLine, 'ColorId'));
        line.parmStyleId(HSMobileOpsOrderLine::jsonStr(jLine, 'StyleId'));
        line.parmBatchId(HSMobileOpsOrderLine::jsonStr(jLine, 'BatchId'));
        line.parmSerialId(HSMobileOpsOrderLine::jsonStr(jLine, 'SerialId'));
        line.parmLocationId(HSMobileOpsOrderLine::jsonStr(jLine, 'LocationId'));
        line.parmQty(HSMobileOpsOrderLine::jsonNum(jLine, 'Qty'));
        line.parmUnitId(HSMobileOpsOrderLine::jsonStr(jLine, 'UnitId'));
        line.parmPrice(HSMobileOpsOrderLine::jsonNum(jLine, 'Price'));
        line.parmPriceUnit(HSMobileOpsOrderLine::jsonNum(jLine, 'PriceUnit'));
        line.parmPriceOverride(strLwr(HSMobileOpsOrderLine::jsonStr(jLine, 'PriceOverride')) == 'true');
        result.addEnd(line);
    }
    return result;
}

private static str jsonStr(Newtonsoft.Json.Linq.JObject _obj, str _property)
{
    Newtonsoft.Json.Linq.JToken token = _obj ? _obj.get_Item(_property) : null;

    return token == null ? '' : token.ToString();
}

private static real jsonNum(Newtonsoft.Json.Linq.JObject _obj, str _property)
{
    str value = HSMobileOpsOrderLine::jsonStr(_obj, _property);

    return value ? str2num(value) : 0;
}

/// <summary>
/// The bin (WMSLocationId) - a return line is issued from it; a stock row says where it lies.
/// </summary>
[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}
